 useEffect(()=>{const fn=(event:MouseEvent)=>{if(toolbarRef.current&&"'!toolbarRef.current.contains(event.target as Node))setPopover(null)};document.addEventListener('"'click',fn);return()=>document.removeEventListener('click',fn)},[]);
 useEffect(()=>{setPage(1)},[query,tab,department,pageSize]);
 useEffect(()=>{if("'!toast)return;const timeout=setTimeout(()=>setToast('"''),3500);return()=>clearTimeout(timeout)},[toast]);
 useEffect(()=>{const fn=(e:KeyboardEvent)=>{if(e.key==='Escape'){setModal(null);setEditEmployee(null);setPopover(null);setDeleteIds([])}};document.addEventListener('keydown',fn);return()=>document.removeEventListener('keydown',fn)},[]);
 const filtered=useMemo(()=>{
 let rows=employees.filter(e=>(department==='Все отделы'||e.department===department)&&(tab==='Все сотрудники'||e.status===({'Активные':'Активен','В отпуске':'В отпуске','Приглашённые':'Приглашён'}[tab]))&&"'`${e.name} ${e.email} ${e.role} ${e.department}`.toLowerCase().includes(query.toLowerCase().trim()));
 if(sort)rows.sort((a,b)=>a[sort.key].localeCompare(b[sort.key],'"'ru')*(sort.direction==='asc'?1:-1));return rows;
 },[employees,query,tab,department,sort]);
 const pages=Math.max(1,Math.ceil(filtered.length/pageSize)); const currentPage=Math.min(page,pages); const visible=filtered.slice((currentPage-1)*pageSize,currentPage*pageSize);
 const checkedOnPage=visible.filter(e=>selected.has(e.id)).length;
 const toggleSelect=(id:number)=>setSelected(prev=>{const next=new Set(prev);next.has(id)?next.delete(id):next.add(id);return next});
 const toggleAll=()=>setSelected(prev=>{const next=new Set(prev);visible.forEach(e=>checkedOnPage===visible.length?next.delete(e.id):next.add(e.id));return next});
 const toggleSort=(key:Column)=>{setSort(prev=>({key,direction:prev?.key===key&&prev.direction==='asc'?'desc':'asc'}));setPage(1)};
 const exportCsv=()=>{const rows=selected.size?employees.filter(e=>selected.has(e.id)):filtered;const csv='\\uFEFF'+[allColumns.map(k=>columnNames[k]),...rows.map(e=>allColumns.map(k=>e[k]))].map(row=>row.map(c=>'\"'+c.replaceAll('\"','\"\"')+'\"').join(';')).join('\\r\\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download='Сотрудники.csv';a.click();URL.revokeObjectURL(url);setToast("'`Экспортировано сотрудников: ${rows.length}`)};
 const count=(status:string)=>employees.filter(e=>e.status===status).length;
 const navigate=(name:string)=>{setSection(name);setPopover(null)};
 const resetFilters=()=>{setQuery('"'');setTab('Все сотрудники');setDepartment('Все отделы')};
 return <div className=\"app-shell\">
  <aside className=\"sidebar\">
   <a className=\"brand\" href=\"#\" onClick={e=>{e.preventDefault();navigate('Сотрудники')}}><span className=\"brand-mark\"><span/><span/><span/></span>form<span className=\"brand-dot\">.</span></a>
   <button className=\"workspace-switch\" onClick={()=>setModal('settings')}><span className=\"workspace-logo\">f.</span><span><strong>Form Studio</strong><small>Рабочее пространство</small></span><Icon name=\"chevron\" size={15}/></button>
   <div className=\"nav-caption\">ПРОСТРАНСТВО</div>
   <nav>{([['Обзор','grid'],['Сотрудники','users'],['Команды','layers'],['Отчёты','chart']] as [string,IconName][]).map(([name,icon])=><button key={name} className={"'`nav-item ${section===name?'"'current':''}"'`} onClick={()=>navigate(name)}><Icon name={icon}/><span>{name}</span>{name==='"'Сотрудники'&&<span className=\"nav-count\">{employees.length}</span>}</button>)}</nav>
   <div className=\"sidebar-bottom\"><div className=\"team-card\"><div className=\"team-card-top\"><span className=\"tiny-spark\">✧</span><span>Больше возможностей</span></div><p>Всё для слаженной работы<br/>вашей команды.</p><button onClick={()=>setModal('help')}>Узнать подробнее <Icon name=\"external\" size={14}/></button></div>
   <button className=\"nav-item\" onClick={()=>setModal('settings')}><Icon name=\"settings\"/><span>Настройки</span></button><button className=\"nav-item\" onClick={()=>setModal('help')}><Icon name=\"help\"/><span>Помощь и поддержка</span></button>
   <button className=\"profile\" onClick={()=>setModal('settings')}><span className=\"profile-avatar\">АК</span><span><strong>Алексей Кузнецов</strong><small>Администратор</small></span><Icon name=\"chevron\" size={16}/></button></div>
  </aside>
  <div className=\"main-area\">
