   <main>
    <div className=\"page-heading\"><div><div className=\"title-line\"><h1>{section}</h1>{section==='Сотрудники'&&<span className=\"title-count\">{employees.length}</span>}</div><p>{section==='Сотрудники'?'Ваша команда в одном месте. Управляйте сотрудниками и оставайтесь на связи.':section==='Команды'?'Люди, которые создают результат. Найдите свою команду.':section==='Отчёты'?'Актуальные данные о вашей команде, всегда под рукой.':'Главное о вашей команде и рабочем пространстве.'}</p></div><div className=\"heading-actions\"><button className=\"button\" onClick={exportCsv}><Icon name=\"download\" size={17}/>Экспорт</button><button className=\"button primary\" onClick={()=>setModal('add')}><Icon name=\"plus\" size={18}/>Добавить сотрудника</button></div></div>
    <div className=\"stats-grid\">
    {[{label:'Всего сотрудников',value:employees.length,icon:'users' as IconName,note:<><span className=\"stat-growth\">↗ +12%</span><span>к прошлому месяцу</span></>},{label:'Активные',value:count('Активен'),icon:'check' as IconName,note:<><span className=\"stat-dot green\"/><span>Готовы к новым задачам</span></>},{label:'Отделы',value:new Set(employees.map(e=>e.department)).size,icon:'layers' as IconName,note:<><span>Вместе к общим целям</span></>},{label:'Приглашённые',value:count('Приглашён'),icon:'mail' as IconName,note:<><span className=\"stat-dot orange\"/><span>Ожидают присоединения</span></>}].map(s=><div className=\"stat-card\" key={s.label}><div className=\"stat-top\"><span>{s.label}</span><Icon name={s.icon} size={18}/></div><strong className=\"stat-value\">{s.value}</strong><div className=\"stat-note\">{s.note}</div></div>)}
    </div>
    {section==='Команды'?<div className=\"department-grid\">{departments.map(d=><button className=\"department-card\" key={d} onClick={()=>{setDepartment(d);setSection('Сотрудники')}}><span className={"'`department department-${departments.indexOf(d)}`}><Icon name="layers" size={20}/></span><h2>{d}</h2><p>{employees.filter(e=>e.department===d).length} сотрудников</p><span className="team-avatars">{employees.filter(e=>e.department===d).slice(0,5).map(e=><Avatar employee={e} key={e.id} small/>)}</span><span className="view-team">Открыть команду <Icon name="chevron" size={15}/></span></button>)}</div>:section==='"'Отчёты'?<section className=\"report-panel\"><span className=\"report-icon\"><Icon name=\"chart\" size={32}/></span><h2>Отчёт по сотрудникам</h2><p>Имена, должности, отделы и статусы всех сотрудников вашего пространства.</p><button className=\"button primary\" onClick={exportCsv}><Icon name=\"download\" size={17}/>Скачать CSV</button><small>Совместим с Excel, Numbers и Google Таблицами</small></section>:<section className=\"table-card\">
     <div className=\"table-top\"><div><h2>{section==='Обзор'?'Ваша команда':'Список сотрудников'}</h2><span className=\"table-subtitle\">Люди, с которыми всё получается</span></div><span className=\"table-total\">{employees.length} сотрудников</span></div>
