     <div className=\"table-toolbar\" ref={toolbarRef}><div className=\"search-field\"><Icon name=\"search\" size={18}/><input placeholder=\"Поиск по имени, почте или должности...\" aria-label=\"Поиск сотрудников\" value={query} onChange={e=>setQuery(e.target.value)}/>{query?<button className=\"icon-button\" onClick={()=>setQuery('')} aria-label=\"Очистить поиск\"><Icon name=\"close\" size={15}/></button>:<kbd>⌘ K</kbd>}</div><div className=\"toolbar-actions\"><div className=\"popover-anchor\"><button className={"'`button ${department!=='"'Все отделы'?'filter-applied':''}"'`} aria-expanded={popover==='"'filter'} onClick={()=>setPopover(popover==='filter'?null:'filter')}><Icon name=\"filter\" size={16}/>Фильтры{department"'!=='"'Все отделы'&&<span className=\"filter-count\">1</span>}</button>{popover==='filter'&&<div className=\"popover filter-popover\"><strong>Отдел</strong>{['Все отделы',...departments].map(d=><button key={d} className=\"popover-option\" onClick={()=>{setDepartment(d);setPopover(null)}}>{d}{d===department&&<Icon name=\"check\" size={16}/>}</button>)}</div>}</div><div className=\"popover-anchor\"><button className=\"button\" aria-expanded={popover==='columns'} onClick={()=>setPopover(popover==='columns'?null:'columns')}><Icon name=\"columns\" size={16}/>Колонки</button>{popover==='columns'&&<div className=\"popover columns-popover\"><strong>Показывать колонки</strong>{allColumns.map(c=><label key={c}><CheckBox checked={columns.includes(c)} onChange={()=>setColumns(old=>old.includes(c)?old.length>1?old.filter(k=>k"'!==c):old:allColumns.filter(k=>old.includes(k)||k===c))} label={columnNames[c]}/>{columnNames[c]}</label>)}</div>}</div></div></div>
     {department!=='"'Все отделы'&&<div className=\"active-filters\"><span>Отдел: {department}<button onClick={()=>setDepartment('Все отделы')} aria-label=\"Сбросить отдел\"><Icon name=\"close\" size={13}/></button></span><button onClick={resetFilters}>Сбросить фильтры</button></div>}
     {selected.size>0&&<div className=\"selection-bar\"><span><strong>Выбрано: {selected.size}</strong><button onClick={()=>setSelected(new Set())}>Снять выделение</button></span><span><button onClick={exportCsv}><Icon name=\"download\" size={15}/>Экспортировать</button><button className=\"delete-action\" onClick={()=>setDeleteIds([...selected])}>Удалить</button></span></div>}
     <div className=\"table-scroll\"><table><thead><tr><th className=\"checkbox-cell\"><CheckBox checked={visible.length>0&&checkedOnPage===visible.length} mixed={checkedOnPage>0&&checkedOnPage<visible.length} onChange={toggleAll} label=\"Выбрать все строки на странице\"/></th>{columns.map(c=><th key={c} className={"'`column-${c}`} aria-sort={sort?.key===c?sort.direction==='"'asc'?'ascending':'descending':'none'}><button className=\"sort-button\" onClick={()=>toggleSort(c)}>{columnNames[c]}<span className={"'`sort-icon ${sort?.key===c?'"'sorted':''} "'${sort?.key===c&&sort.direction==='"'asc'?'ascending':''}"'`}><Icon name="arrow" size={13}/></span></button></th>)}<th className="row-menu-cell"><span className="sr-only">Действия</span></th></tr></thead><tbody>{visible.map(employee=><tr key={employee.id} className={selected.has(employee.id)?'"'row-selected':''}><td className=\"checkbox-cell\"><CheckBox checked={selected.has(employee.id)} onChange={()=>toggleSelect(employee.id)} label={"'`Выбрать: ${employee.name}`}/></td>{columns.map(c=><td key={c} className={`column-${c}`}>{c==='"'name'?<div className=\"employee-cell\"><Avatar employee={employee}/><div><button className=\"employee-name\" onClick={()=>setEditEmployee(employee)}>{employee.name}</button><span className=\"employee-email\">{employee.email}</span></div></div>:c==='department'?<span className={"'`department department-${departments.indexOf(employee.department)}`}>{employee.department}</span>:c==='"'status'?<Status value={employee.status}/>:c==='date'?<span className=\"date-cell\">{new Date(employee.date+'T12:00:00').toLocaleDateString('ru-RU',{day:'2-digit',month:'short',year:'numeric'}).replace(' г.','')}</span>:employee[c]}</td>)}<td className=\"row-menu-cell\"><button className=\"icon-button\" aria-label={"'`Редактировать: ${employee.name}`} onClick={()=>setEditEmployee(employee)}><Icon name="more" size={19}/></button></td></tr>)}</tbody></table>{!visible.length&&<div className="empty-state"><Icon name="search" size={30}/><h3>Сотрудники не найдены</h3><p>Попробуйте изменить запрос или сбросить фильтры.</p><button className="button" onClick={resetFilters}>Сбросить фильтры</button></div>}</div>
     <div className="pagination"><div className="pagination-description">Показано <strong>{filtered.length?(currentPage-1)*pageSize+1:0}–{Math.min(currentPage*pageSize,filtered.length)}</strong> из <strong>{filtered.length}</strong><span className="page-size-divider"/><label>На странице <select value={pageSize} onChange={e=>setPageSize(Number(e.target.value))}><option value="8">8</option><option value="16">16</option><option value="24">24</option></select></label></div><div className="page-buttons"><button className="page-arrow" disabled={currentPage===1} onClick={()=>setPage(p=>p-1)} aria-label="Предыдущая страница"><Icon name="chevron" className="rotate" size={15}/><span>Назад</span></button>{Array.from({length:pages},(_,i)=>i+1).map(p=><button key={p} aria-label={`Страница ${p}`} aria-current={currentPage===p?'"'page':undefined} className={"'`page-number ${currentPage===p?'"'current-page':''}"'`} onClick={()=>setPage(p)}>{p}</button>)}<button className="page-arrow" disabled={currentPage===pages} onClick={()=>setPage(p=>p+1)} aria-label="Следующая страница"><span>Далее</span><Icon name="chevron" size={15}/></button></div></div>
    </section>}
    <footer className="page-footer"><span>Хорошая работа начинается с хорошей команды.</span><span><span className="footer-dot"/>Ваши данные в безопасности</span></footer>
   </main>
  </div>
  {(modal||editEmployee||deleteIds.length>0)&&<div className="modal-backdrop" onClick={()=>{setModal(null);setEditEmployee(null);setDeleteIds([])}}><div className="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title" onClick={e=>e.stopPropagation()}><button className="icon-button modal-close" aria-label="Закрыть" onClick={()=>{setModal(null);setEditEmployee(null);setDeleteIds([])}}><Icon name="close"/></button>{(modal==='"'add'||editEmployee)?<EmployeeForm employee={editEmployee} onDelete={()=>{setDeleteIds([editEmployee"'!.id]);setEditEmployee(null)}} onCancel={()=>{setModal(null);setEditEmployee(null)}} onSave={values=>{if(editEmployee){setEmployees(old=>old.map(e=>e.id===editEmployee.id?{...e,...values}:e));setToast('"'Данные сотрудника обновлены')}else{setEmployees(old=>[...old,{...values,id:Math.max(0,...old.map(e=>e.id))+1,date:new Date().toISOString().slice(0,10),color:old.length%8}]);setToast('Сотрудник добавлен')}setModal(null);setEditEmployee(null)}}/>:deleteIds.length>0?<><span className=\"modal-eyebrow\">УПРАВЛЕНИЕ КОМАНДОЙ</span><h2 id=\"dialog-title\">Удалить сотрудников?</h2><p>Выбранные записи ({deleteIds.length}) будут удалены из рабочего пространства.</p><div className=\"modal-actions\"><button className=\"button\" onClick={()=>setDeleteIds([])}>Отмена</button><button className=\"button danger\" onClick={()=>{setEmployees(old=>old.filter(e=>"'!deleteIds.includes(e.id)));setSelected(old=>new Set([...old].filter(id=>!deleteIds.includes(id))));setDeleteIds([]);setToast('"'Выбранные сотрудники удалены')}}>Удалить</button></div></>:modal==='settings'?<><span className=\"modal-eyebrow\">РАБОЧЕЕ ПРОСТРАНСТВО</span><h2 id=\"dialog-title\">Настройки Form Studio</h2><p>Профиль администратора и параметры отображения.</p><div className=\"settings-profile\"><span className=\"profile-avatar\">АК</span><div><strong>Алексей Кузнецов</strong><p>Администратор · alexey@form.team</p></div></div><label className=\"form-label\">Строк на странице<select value={pageSize} onChange={e=>setPageSize(Number(e.target.value))}><option value={8}>8</option><option value={16}>16</option><option value={24}>24</option></select></label><div className=\"modal-actions\"><button className=\"button primary\" onClick={()=>setModal(null)}>Готово</button></div></>:<><span className=\"modal-eyebrow\">FORM · ЦЕНТР ПОМОЩИ</span><h2 id=\"dialog-title\">Всё для вашей команды</h2><p>Управляйте сотрудниками в одном рабочем пространстве.</p><div className=\"help-item\"><Icon name=\"arrow\"/><div><strong>Сортировка и поиск</strong><p>Нажмите на заголовок колонки, чтобы изменить порядок. Поиск работает по имени, почте, должности и отделу.</p></div></div><div className=\"help-item\"><Icon name=\"check\"/><div><strong>Выбор сотрудников</strong><p>Чекбокс в заголовке выбирает текущую страницу. Выбор сохраняется при переходе между страницами.</p></div></div><div className=\"help-item\"><Icon name=\"download\"/><div><strong>Экспорт данных</strong><p>Скачайте выбранных сотрудников или весь отфильтрованный список в формате CSV.</p></div></div><button className=\"button primary help-close\" onClick={()=>setModal(null)}>Всё понятно</button></>}</div></div>}
  {toast&&<div className=\"toast\" role=\"status\"><span><Icon name=\"check\" size={17}/></span>{toast}<button className=\"icon-button\" onClick={()=>setToast('')} aria-label=\"Закрыть уведомление\"><Icon name=\"close\" size={16}/></button></div>}
 </div>;
}
function EmployeeForm({employee,onSave,onCancel,onDelete}:{employee:Employee|null;onSave:(values:Pick<Employee,'name'|'email'|'role'|'department'|'status'>)=>void;onCancel:()=>void;onDelete:()=>void}) {
 return <form onSubmit={e=>{e.preventDefault();const data=new FormData(e.currentTarget);onSave({name:String(data.get('name')).trim(),email:String(data.get('email')).trim(),role:String(data.get('role')).trim(),department:String(data.get('department')),status:String(data.get('status'))})}}><span className=\"modal-eyebrow\">ВАША КОМАНДА</span><h2 id=\"dialog-title\">{employee?'Профиль сотрудника':'Новый сотрудник'}</h2><p>{employee?'Данные и статус в рабочем пространстве.':'Добавьте того, с кем будете создавать новое.'}</p><label className=\"form-label\">Имя и фамилия<input name=\"name\" required pattern=\".*\\S.*\" defaultValue={employee?.name} placeholder=\"Например, Анна Смирнова\" autoFocus/></label><label className=\"form-label\">Электронная почта<input name=\"email\" type=\"email\" required defaultValue={employee?.email} placeholder=\"name@form.team\"/></label><label className=\"form-label\">Должность<input name=\"role\" required pattern=\".*\\S.*\" defaultValue={employee?.role} placeholder=\"Например, Product Designer\"/></label><div className=\"form-row\"><label className=\"form-label\">Отдел<select name=\"department\" defaultValue={employee?.department??'Дизайн'}>{departments.map(d=><option key={d}>{d}</option>)}</select></label><label className=\"form-label\">Статус<select name=\"status\" defaultValue={employee?.status??'Приглашён'}>{['Активен','В отпуске','Приглашён'].map(s=><option key={s}>{s}</option>)}</select></label></div><div className=\"modal-actions\">{employee&&<button type=\"button\" className=\"button text-danger\" onClick={onDelete}>Удалить</button>}<button type=\"button\" className=\"button\" onClick={onCancel}>Отмена</button><button className=\"button primary\" type=\"submit\">{employee?'Сохранить':'Добавить сотрудника'}</button></div></form>
}
