function EmployeeForm({employee,onSave,onCancel,onDelete}:{employee:Employee|null;onSave:(values:Pick<Employee,'name'|'email'|'role'|'department'|'status'>)=>void;onCancel:()=>void;onDelete:()=>void}) {
